use realm_agent::{model::*,task::TaskEngine};
use std::collections::BTreeSet;
fn world(class:u8)->WorldView{
 let p=Position{map:1,x:1232.41,y:-4411.27,z:22.9853,orientation:0.};
 let me=Entity{guid:10,kind:Kind::Player,entry:0,name:Some("Fixture".into()),position:Some(p),health:Some(100),max_health:Some(100),mana:Some(100),max_mana:Some(100),level:Some(60),class:Some(class),rage:None,flags:0,duel_arbiter:0,auras:BTreeSet::new(),target:None,updated_ms:0};
 let mut w=WorldView{connected:true,class,self_guid:10,character:"Fixture".into(),position:Some(p),..Default::default()};w.objects.insert(10,me);w
}
fn spec()->TaskSpec{serde_json::from_str(include_str!("../config/task-horde.example.json")).unwrap()}
fn advance(e:&mut TaskEngine,w:&mut WorldView){w.now_ms+=1000;e.tick(w);}
#[test]fn rejects_unready_and_unknown_class(){let mut e=TaskEngine::default();let mut w=world(5);assert!(e.command(Command::Start(spec()),&w).is_err());w.class=8;w.connected=false;assert!(e.command(Command::Start(spec()),&w).is_err());}
#[test]fn warrior_needs_inn_and_navigation_failure_blocks(){let mut e=TaskEngine::default();let mut w=world(1);e.command(Command::Start(spec()),&w).unwrap();advance(&mut e,&mut w);assert_eq!(e.status().unwrap().phase,"travelling_inn");w.now_ms+=1000;assert!(matches!(e.tick(&w).actions.first(),Some(Action::Navigate(_))));e.event(GameEvent::NavigationFailed{reason:"no_path".into()},&w);assert_eq!(e.status().unwrap().phase,"blocked");}
#[test]fn mage_conjure_waits_for_inventory_confirmation(){let mut e=TaskEngine::default();let mut w=world(8);w.spells.insert(10145);w.spells.insert(10140);e.command(Command::Start(spec()),&w).unwrap();advance(&mut e,&mut w);assert_eq!(e.status().unwrap().phase,"conjuring");w.now_ms+=1000;assert!(e.tick(&w).actions.iter().any(|a|matches!(a,Action::Cast{spell:10145,..})));assert_eq!(e.status().unwrap().phase,"conjuring");w.inventory.push(InventoryItem{guid:1,entry:8076,count:20,bag:255,slot:23});w.inventory.push(InventoryItem{guid:2,entry:8079,count:20,bag:255,slot:24});w.now_ms+=6000;e.tick(&w);assert_eq!(e.status().unwrap().phase,"travelling_arena");}
#[test]fn duel_and_recovery_loop_are_observed_not_assumed(){let mut e=TaskEngine::default();let mut w=world(1);let mut s=spec();s.opponents=vec![20];w.inventory.push(InventoryItem{guid:1,entry:8952,count:20,bag:255,slot:23});let mut peer=w.me().unwrap().clone();peer.guid=20;w.objects.insert(20,peer);e.command(Command::Start(s),&w).unwrap();for _ in 0..5{advance(&mut e,&mut w);}assert_eq!(e.status().unwrap().phase,"challenging");w.now_ms+=1000;let effect=e.tick(&w);assert!(effect.actions.iter().any(|a|matches!(a,Action::Cast{spell:7266,..})));e.event(GameEvent::DuelRequested{arbiter:100,challenger:10},&w);e.event(GameEvent::DuelCountdown{seconds:3},&w);advance(&mut e,&mut w);assert_eq!(e.status().unwrap().phase,"countdown");for _ in 0..3{advance(&mut e,&mut w);}assert_eq!(e.status().unwrap().phase,"duelling");e.event(GameEvent::DuelComplete{started:true},&w);assert_eq!(e.status().unwrap().phase,"recovering");advance(&mut e,&mut w);assert_eq!(e.status().unwrap().phase,"checking_supplies");assert_eq!(e.status().unwrap().duels,1);}
#[test]fn no_allowlist_never_challenges_and_pause_stops(){let mut e=TaskEngine::default();let mut w=world(1);w.inventory.push(InventoryItem{guid:1,entry:8952,count:20,bag:255,slot:23});e.command(Command::Start(spec()),&w).unwrap();for _ in 0..8{w.now_ms+=1000;assert!(!e.tick(&w).actions.iter().any(|a|matches!(a,Action::Cast{spell:7266,..})));}let result=e.command(Command::Pause,&w).unwrap();assert!(result.actions.iter().any(|a|matches!(a,Action::StopMoving)));assert!(e.tick(&w).actions.is_empty());}
#[test]fn group_invite_is_accepted_without_changing_task(){let mut e=TaskEngine::default();let w=world(1);e.command(Command::Start(spec()),&w).unwrap();let effect=e.event(GameEvent::GroupInvite{inviter:99},&w);assert!(effect.actions.iter().any(|a|matches!(a,Action::AcceptGroup)));assert_eq!(e.status().unwrap().phase,"checking_supplies");}
#[test]fn city_duel_selects_same_task_again_after_one_hour(){let mut e=TaskEngine::default();let mut w=world(1);let mut s=spec();s.max_duels=None;s.duration_secs=3600;e.command(Command::Start(s),&w).unwrap();w.now_ms=3_600_001;let effect=e.tick(&w);assert!(effect.events.iter().any(|(k,_)|k=="task.completed"));assert!(effect.events.iter().any(|(k,_)|k=="task.selected"));assert_eq!(e.status().unwrap().phase,"checking_supplies");assert_eq!(e.status().unwrap().id,2);}

#[test]fn nonempty_supply_does_not_return_inn_each_round(){let mut e=TaskEngine::default();let mut w=world(1);w.inventory.push(InventoryItem{guid:1,entry:8952,count:19,bag:255,slot:23});e.command(Command::Start(spec()),&w).unwrap();advance(&mut e,&mut w);assert_eq!(e.status().unwrap().phase,"travelling_arena");}
#[test]fn invalid_schema_and_zero_limit_rejected(){for mut s in [spec(),spec()]{s.schema_version=2;assert!(TaskEngine::default().command(Command::Start(s),&world(1)).is_err());}let mut s=spec();s.max_duels=Some(0);assert!(TaskEngine::default().command(Command::Start(s),&world(1)).is_err());}
#[test]fn cancelled_task_cannot_resume(){let mut e=TaskEngine::default();let w=world(1);e.command(Command::Start(spec()),&w).unwrap();e.command(Command::Cancel,&w).unwrap();assert!(e.command(Command::Resume,&w).is_err());assert_eq!(e.status().unwrap().phase,"cancelled");}
fn duel_setup()->(TaskEngine,WorldView){let mut e=TaskEngine::default();let w=world(1);let mut s=spec();s.opponents=vec![20];e.command(Command::Start(s),&w).unwrap();e.event(GameEvent::DuelRequested{arbiter:100,challenger:20},&w);(e,w)}
#[test]fn duplicate_duel_messages_do_not_accept_or_count_twice(){let(mut e,w)=duel_setup();assert!(e.event(GameEvent::DuelRequested{arbiter:100,challenger:20},&w).actions.is_empty());e.event(GameEvent::DuelComplete{started:true},&w);assert!(e.event(GameEvent::DuelComplete{started:true},&w).events.is_empty());assert_eq!(e.status().unwrap().duels,1);e.event(GameEvent::DuelWinner{winner:w.character.clone(),loser:"Other".into()},&w);e.event(GameEvent::DuelWinner{winner:w.character.clone(),loser:"Other".into()},&w);assert_eq!(e.status().unwrap().wins,1);}
#[test]fn deadline_waits_for_duel_completion(){let(mut e,mut w)=duel_setup();w.now_ms=e.status().unwrap().deadline_ms+1;let effects=e.tick(&w);assert!(effects.events.iter().any(|(k,_)|k=="task.rotation_pending"));assert!(!effects.actions.iter().any(|a|matches!(a,Action::CancelDuel(_))));assert_eq!(e.status().unwrap().id,1);e.event(GameEvent::DuelComplete{started:true},&w);e.tick(&w);assert_eq!(e.status().unwrap().id,2);}
#[test]fn recovery_with_empty_bag_requests_supply(){let(mut e,mut w)=duel_setup();e.event(GameEvent::DuelComplete{started:true},&w);w.objects.get_mut(&10).unwrap().health=Some(50);w.now_ms+=1000;e.tick(&w);assert_eq!(e.status().unwrap().phase,"travelling_inn");}
#[test]fn preparation_waits_for_buff_confirmation(){let mut e=TaskEngine::default();let mut w=world(8);w.spells.insert(1459);w.inventory.push(InventoryItem{guid:1,entry:8076,count:20,bag:255,slot:23});w.inventory.push(InventoryItem{guid:2,entry:8079,count:20,bag:255,slot:24});e.command(Command::Start(spec()),&w).unwrap();for _ in 0..3{advance(&mut e,&mut w);}assert_eq!(e.status().unwrap().phase,"preparing");w.objects.get_mut(&10).unwrap().auras.insert(1459);w.now_ms+=2500;e.tick(&w);assert_eq!(e.status().unwrap().phase,"seeking");}

#[test]fn accepts_incoming_human_challenge_outside_proactive_allowlist(){let mut e=TaskEngine::default();let w=world(8);let mut s=spec();s.opponents=vec![];e.command(Command::Start(s),&w).unwrap();let fx=e.event(GameEvent::DuelRequested{arbiter:987,challenger:99},&w);assert!(fx.actions.iter().any(|a|matches!(a,Action::Select(99))));assert!(fx.actions.iter().any(|a|matches!(a,Action::AcceptDuel(987))));assert_eq!(e.status().unwrap().opponent,Some(99));}
#[test]fn incoming_challenge_waits_for_recovery_then_accepts(){let mut e=TaskEngine::default();let mut w=world(8);e.command(Command::Start(spec()),&w).unwrap();w.objects.get_mut(&10).unwrap().health=Some(50);w.inventory.push(InventoryItem{guid:1,entry:8076,count:20,bag:255,slot:23});w.inventory.push(InventoryItem{guid:2,entry:8079,count:20,bag:255,slot:24});let fx=e.event(GameEvent::DuelRequested{arbiter:987,challenger:99},&w);assert!(!fx.actions.iter().any(|a|matches!(a,Action::CancelDuel(_)|Action::AcceptDuel(_))));w.objects.get_mut(&10).unwrap().health=Some(100);w.now_ms+=1000;assert!(e.tick(&w).actions.iter().any(|a|matches!(a,Action::AcceptDuel(987))));}

#[test]fn incoming_challenge_survives_empty_bag_supply_phase(){let mut e=TaskEngine::default();let mut w=world(8);e.command(Command::Start(spec()),&w).unwrap();w.objects.get_mut(&10).unwrap().health=Some(50);w.spells.insert(10145);e.event(GameEvent::DuelRequested{arbiter:987,challenger:99},&w);w.now_ms+=1000;e.tick(&w);assert_eq!(e.status().unwrap().phase,"conjuring");w.objects.get_mut(&10).unwrap().health=Some(100);w.now_ms+=1000;let fx=e.tick(&w);assert_eq!(fx.actions.iter().filter(|a|matches!(a,Action::AcceptDuel(987))).count(),1);assert!(!fx.actions.iter().any(|a|matches!(a,Action::Navigate(_)|Action::Cast{spell:7266,..})));}

#[test]fn arcane_brilliance_satisfies_preparation_intellect(){let mut e=TaskEngine::default();let mut w=world(8);w.spells.insert(10157);w.objects.get_mut(&10).unwrap().auras.insert(23028);w.inventory.push(InventoryItem{guid:1,entry:8076,count:20,bag:255,slot:23});w.inventory.push(InventoryItem{guid:2,entry:8079,count:20,bag:255,slot:24});e.command(Command::Start(spec()),&w).unwrap();for _ in 0..5{w.now_ms+=1000;assert!(!e.tick(&w).actions.iter().any(|a|matches!(a,Action::Cast{spell:10157,..})));}assert_ne!(e.status().unwrap().phase,"blocked");}
